#!/usr/bin/env python3
"""DrawDock design tokens: single source of truth.

Writes:
  assets/tokens/drawdock-tokens.json
  assets/android/res/values/dd_colors.xml
  assets/android/res/values/dd_dimens.xml
  assets/compose/DrawDockTokens.kt   (package placeholder: com.drawdock.ui.theme)
Usage: python3 scripts/build_tokens.py   (run from the skill root)
"""
import json, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

COLORS = {  # name: ARGB hex (AARRGGBB)
    # brand
    "brand_navy": "FF0B1B3A", "brand_navy_surface": "FF13284F", "brand_navy_raised": "FF1C3566",
    "brand_cyan": "FF22D3EE", "brand_coral": "FFFF6B57", "brand_light": "FFF0F7FF",
    "on_dark": "FFE6F0FF", "on_dark_muted": "FF8FA3C4", "danger": "FFFF5470",
    # radial menu
    "menu_surface": "F00B1B3A", "menu_ring_stroke": "5922D3EE", "menu_divider": "1FE6F0FF",
    "menu_item_pressed": "3822D3EE", "menu_item_hover": "2422D3EE",
    "menu_item_selected_bg": "FF22D3EE", "menu_item_selected_icon": "FF0B1B3A",
    "menu_center_surface": "FF13284F", "menu_center_stroke": "4D22D3EE",
    "menu_toggle_on": "FF22D3EE", "menu_shadow": "52000000",
    # annotation palette (Style > Color), fixed order
    "ink_red": "FFEF4444", "ink_orange": "FFF97316", "ink_yellow": "FFFACC15", "ink_green": "FF22C55E",
    "ink_blue": "FF3B82F6", "ink_black": "FF111111", "ink_white": "FFFFFFFF",
    "swatch_outline": "FF8FA3C4",
    # canvas
    "canvas_blackboard": "FF1F2B27", "grid_line_on_light": "1A0B1B3A", "grid_line_on_dark": "1FFFFFFF",
    "selection_stroke": "FF22D3EE", "handle_fill": "FFFFFFFF", "handle_stroke": "FF22D3EE",
    "laser_core": "FFFF4D3D", "laser_glow": "66FF4D3D", "long_press_ring": "FF22D3EE",
    "long_press_track": "3322D3EE",
}
DIMENS = {  # dp unless *_sp
    "menu_diameter": 288, "menu_item_ring_radius": 100, "menu_item_slot": 64, "menu_item_highlight": 56,
    "menu_icon": 24, "menu_label_sp": 11, "menu_center_diameter": 64, "menu_center_label_sp": 9,
    "menu_ring_stroke": 1, "menu_edge_margin": 8, "menu_shadow_blur": 16,
    "swatch_diameter": 26, "swatch_selected_ring": 3, "swatch_outline": 1.5,
    "width_thin": 3, "width_medium": 6, "width_thick": 12,
    "selection_stroke": 1.5, "selection_dash_on": 6, "selection_dash_off": 4,
    "handle_size": 12, "handle_stroke": 2, "handle_touch_target": 40,
    "rotation_handle_size": 16, "rotation_handle_offset": 32,
    "path_vertex": 8, "path_first_vertex_ring": 16, "path_rubber_dash_on": 8, "path_rubber_dash_off": 6,
    "long_press_ring_diameter": 40, "long_press_ring_stroke": 3,
    "grid_spacing": 24, "grid_line": 1,
}
MOTION = {  # ms
    "long_press_total": 550, "long_press_ring_delay": 150,
    "menu_open": 140, "menu_item_stagger": 12, "menu_close": 100,
    "submenu_out": 90, "submenu_in": 140, "laser_trail_fade": 400,
}
MISC = {"highlighter_alpha": 0.35, "disabled_alpha": 0.38, "menu_open_scale_from": 0.88,
        "submenu_out_scale_to": 0.92, "submenu_in_scale_from": 1.06}

def camel(n): 
    p = n.replace("_sp", "Sp").split("_"); return p[0] + "".join(x[:1].upper() + x[1:] for x in p[1:])

def main():
    for d in ["assets/tokens", "assets/android/res/values", "assets/compose"]:
        os.makedirs(os.path.join(ROOT, d), exist_ok=True)
    json.dump({"color": {k: "#" + v for k, v in COLORS.items()}, "dimen_dp": DIMENS, "motion_ms": MOTION, "misc": MISC},
              open(os.path.join(ROOT, "assets/tokens/drawdock-tokens.json"), "w"), indent=2)
    hdr = '<?xml version="1.0" encoding="utf-8"?>\n<!-- DrawDock tokens. Generated by scripts/build_tokens.py -->\n<resources>\n'
    open(os.path.join(ROOT, "assets/android/res/values/dd_colors.xml"), "w").write(
        hdr + "".join(f'    <color name="dd_{k}">#{v}</color>\n' for k, v in COLORS.items()) + "</resources>\n")
    open(os.path.join(ROOT, "assets/android/res/values/dd_dimens.xml"), "w").write(
        hdr + "".join(f'    <dimen name="dd_{k}">{v}{"sp" if k.endswith("_sp") else "dp"}</dimen>\n' for k, v in DIMENS.items())
        + "".join(f'    <integer name="dd_motion_{k}">{v}</integer>\n' for k, v in MOTION.items()) + "</resources>\n")
    kt = ["// DrawDock design tokens. Generated by scripts/build_tokens.py; change the script, not this file.",
          "package com.drawdock.ui.theme  // adjust to the app's package", "",
          "import androidx.compose.ui.graphics.Color", "import androidx.compose.ui.unit.dp", "import androidx.compose.ui.unit.sp", "",
          "object DDColor {"] + [f"    val {camel(k)} = Color(0x{v})" for k, v in COLORS.items()] + [
          "    /** Style > Color, in menu order. */",
          "    val inkPalette = listOf(inkRed, inkOrange, inkYellow, inkGreen, inkBlue, inkBlack, inkWhite)", "}", "",
          "object DDDimen {"] + [f"    val {camel(k)} = {v}.{'sp' if k.endswith('_sp') else 'dp'}" for k, v in DIMENS.items()] + ["}", "",
          "object DDMotion {"] + [f"    const val {camel(k)}Ms = {v}" for k, v in MOTION.items()] + ["}", "",
          "object DDMisc {"] + [f"    const val {camel(k)} = {v}f" for k, v in MISC.items()] + ["}", ""]
    open(os.path.join(ROOT, "assets/compose/DrawDockTokens.kt"), "w").write("\n".join(kt))
    print("tokens written")

if __name__ == "__main__":
    main()
